const input=$json.body ?? $json;
const deal=input.deal ?? input;
const closing=input.closing ?? {};
const dates=input.critical_dates ?? {};
const milestones=Array.isArray(input.milestones)?input.milestones:[];
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const now=Date.now();
const parseDate=v=>{const t=Date.parse(v||'');return Number.isFinite(t)?t:null};
const closingTs=parseDate(dates.closing_date||closing.closing_date);
const assignmentTs=parseDate(dates.assignment_deadline||closing.assignment_deadline);
const terminationTs=parseDate(dates.termination_date);
const openBlockers=blockers.filter(b=>b&&b.resolved!==true&&b.status!=='resolved');
const milestoneState=milestones.map(m=>{const due=parseDate(m.due_date);return {...m,overdue:Boolean(due!==null&&due<now&&m.completed!==true),due_in_hours:due===null?null:Math.round((due-now)/3600000)}});
const overdueMilestones=milestoneState.filter(m=>m.overdue);
const nextMilestone=milestoneState.filter(m=>m.completed!==true&&m.due_in_hours!==null).sort((a,b)=>a.due_in_hours-b.due_in_hours)[0]||null;
const urgentDates=[['closing_date',closingTs],['assignment_deadline',assignmentTs],['termination_date',terminationTs]].filter(([,t])=>t!==null).map(([name,t])=>({name,due_in_hours:Math.round((t-now)/3600000)})).sort((a,b)=>a.due_in_hours-b.due_in_hours);
const nextCriticalDate=urgentDates[0]||null;
const criticalDateOverdue=Boolean(nextCriticalDate&&nextCriticalDate.due_in_hours<0);
const status=criticalDateOverdue||overdueMilestones.length||openBlockers.length?'attention_required':'on_track';
const route=criticalDateOverdue?'critical_date_escalation':overdueMilestones.length?'milestone_escalation':openBlockers.length?'blocker_resolution':'closing_coordination';
return [{json:{workflow_id:'WF-136',workflow_name:'Closing Coordination → Critical Date & Milestone Monitor',status,route,deal_id:deal.id??deal.deal_id??null,lead_id:deal.lead_id??null,property_id:deal.property_id??null,buyer_id:deal.buyer_id??null,critical_dates:{closing_date:dates.closing_date??closing.closing_date??null,assignment_deadline:dates.assignment_deadline??closing.assignment_deadline??null,termination_date:dates.termination_date??null},next_critical_date:nextCriticalDate,milestones:milestoneState,overdue_milestones:overdueMilestones,open_blockers:openBlockers,monitoring:{checked_at:new Date().toISOString(),next_milestone:nextMilestone,critical_date_overdue:criticalDateOverdue},next_workflow:route==='critical_date_escalation'||route==='milestone_escalation'||route==='blocker_resolution'?'human_review':'WF-126 closing coordination & critical date controller',crm_activity:{event_type:'closing_critical_date_milestone_monitor',outcome:status,route,deal_id:deal.id??deal.deal_id??null},idempotency_key:'wf-136:closing-monitor:'+(deal.id??deal.deal_id??input.event_id??'unknown')}}}];
